from pathlib import Path
import json
import pandas as pd
from task3_s3_localization import NOC_ZH, SPORT, event_zh
ROOT=Path(__file__).resolve().parents[2]; TASK=ROOT/'交付文件'/'任务三_专题深挖'/'S3_冠军的保质期'; OUT=TASK/'06_冠军王朝时间轴'; OUT.mkdir(parents=True,exist_ok=True)
s=pd.read_csv(TASK/'02_数据表'/'S3_冠军王朝清单.csv').sort_values(['editions','end_year'],ascending=False)
selected=s[s.editions.ge(3)].head(160).copy()
assert set(selected.NOC) <= NOC_ZH.keys()
assert set(selected.Sport) <= SPORT.keys()
selected['代表团名称']=selected.NOC.map(NOC_ZH)
selected['运动名称']=selected.Sport.map(SPORT)
selected['小项名称']=selected.Event.map(event_zh)
records=selected[['NOC','代表团名称','运动名称','小项名称','start_year','end_year','editions']].to_dict('records')
payload=json.dumps(records,ensure_ascii=False,separators=(',',':'))
html='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>冠军王朝时间轴</title><style>
:root{--纸:#f5f1e8;--墨:#152a30;--金:#c79138;--红:#ad4058;--青:#247487;--线:#d4dad7}*{box-sizing:border-box}body{margin:0;background:var(--纸);color:var(--墨);font-family:"Microsoft YaHei",sans-serif}header{padding:10vh 6vw 6vh;border-bottom:1px solid var(--线)}.眉题{color:var(--金);font-weight:800;letter-spacing:.15em}h1{font-size:clamp(52px,9vw,120px);line-height:.95;margin:.2em 0}.导语{font-size:20px;line-height:1.8;max-width:850px}.数据卡{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:35px}.卡{padding:22px;border:1px solid var(--线);border-radius:18px;background:#fff7}.大数{font-size:40px;font-weight:900;color:var(--青)}main{padding:5vh 6vw}.控制{display:flex;gap:12px;flex-wrap:wrap;position:sticky;top:0;padding:15px 0;background:#f5f1e8e8;backdrop-filter:blur(10px);z-index:4}select{padding:11px 15px;border:1px solid var(--线);border-radius:12px;background:white}.轴{position:relative;margin:35px 0}.轴:before{content:"";position:absolute;left:115px;top:0;bottom:0;width:2px;background:var(--线)}.条{display:grid;grid-template-columns:90px 1fr;gap:45px;margin:22px 0;align-items:center}.届{font-size:30px;font-weight:900;text-align:right;color:var(--金)}.内容{position:relative;padding:18px 22px;border:1px solid var(--线);border-radius:16px;background:#fff8}.内容:before{content:"";position:absolute;left:-53px;top:50%;width:12px;height:12px;border-radius:50%;background:var(--红);transform:translateY(-50%)}.名称{font-size:20px;font-weight:800}.年份{color:#68777d;margin-top:6px}.区间{height:8px;margin-top:15px;background:#e2e7e4;border-radius:8px;overflow:hidden}.填充{height:100%;background:linear-gradient(90deg,var(--金),var(--红))}.说明{padding:6vh 6vw;background:var(--墨);color:var(--纸);line-height:1.8}@media(max-width:700px){.数据卡{grid-template-columns:1fr}.轴:before{left:65px}.条{grid-template-columns:52px 1fr;gap:30px}.届{font-size:22px}.内容:before{left:-37px}}
</style></head><body><header><div class="眉题">任务三 · 创新专题</div><h1>冠军王朝<br>时间轴</h1><p class="导语">一枚金牌是瞬间，连续守住同一小项才构成王朝。选择代表团或项目，查看奥运优势如何延续、断裂和转移。</p><div class="数据卡"><div class="卡"><div class="大数">4,511</div>次冠军控制权转换</div><div class="卡"><div class="大数">29.5%</div>总体控制权延续率</div><div class="卡"><div class="大数">16届</div>最长连续王朝</div></div></header><main><div class="控制"><select id="代表团"><option value="全部">全部代表团</option></select><select id="项目"><option value="全部">全部体育项目</option></select><select id="长度"><option value="3">至少3届</option><option value="5">至少5届</option><option value="8">至少8届</option></select></div><div class="轴" id="轴"></div></main><section class="说明"><h2>如何阅读</h2><p>“连续届数”按该小项连续出现的奥运届次计算，不按自然年份计算。小项停办后重返会进入新的比较序列。并列金牌以冠军集合处理，但王朝严格要求同一个NOC连续夺金。NOC为国际奥委会代表团代码。</p></section><script>const 数据=__DATA__,团=document.querySelector('#代表团'),项=document.querySelector('#项目'),长=document.querySelector('#长度'),轴=document.querySelector('#轴');function 选项(a){return [...new Set(a)].sort((x,y)=>String(x).localeCompare(String(y),'zh-CN'))}团.innerHTML+=[...选项(数据.map(x=>x.NOC))].map(x=>`<option>${x}</option>`).join('');项.innerHTML+=[...选项(数据.map(x=>x.Sport_zh))].map(x=>`<option>${x}</option>`).join('');function 渲染(){let a=数据.filter(x=>(团.value==='全部'||x.NOC===团.value)&&(项.value==='全部'||x.Sport_zh===项.value)&&x.editions>=+长.value).slice(0,80);轴.innerHTML=a.map(x=>`<article class="条"><div class="届">${x.editions}届</div><div class="内容"><div class="名称">${x.NOC} · ${x.Event_zh}</div><div class="年份">${x.start_year}—${x.end_year}　${x.Sport_zh}</div><div class="区间"><div class="填充" style="width:${x.editions/16*100}%"></div></div></div></article>`).join('')||'<p>当前条件没有符合的王朝记录。</p>'}for(const x of [团,项,长])x.onchange=渲染;渲染();</script></body></html>'''.replace('__DATA__',payload)
html=html.replace('团.innerHTML+=[...选项(数据.map(x=>x.NOC))].map(x=>`<option>${x}</option>`).join(\'\');', '团.innerHTML+=[...选项(数据.map(x=>x.代表团名称))].map(x=>`<option>${x}</option>`).join(\'\');')
html=html.replace('x.NOC===团.value', 'x.代表团名称===团.value')
html=html.replace('x.Sport_zh', 'x.运动名称').replace('x.Event_zh', 'x.小项名称')
html=html.replace('${x.NOC} · ${x.小项名称}', '${x.代表团名称} · ${x.小项名称}')
html=html.replace('NOC为国际奥委会代表团代码。', '页面使用中文代表团名称展示；原始数据保留国际奥委会代表团代码，以区分历史政体和特殊身份。')
(OUT/'index.html').write_text(html,encoding='utf-8'); print(OUT/'index.html')
